preConditionHook:
// RangeWidthBelowAtrMultiple held for a run: the height of the last N bars is
// no more than K times the N-bar ATR on each of the last `consecutiveBars`
// bars -- Grimes's consolidation that has lasted markedly longer than the
// trend's usual pauses (A-list TightRangeRunLength, G10-07, merge decision 10).
// Authored 2026-09-22 as a `consecutiveBars` input on RangeWidthBelowAtrMultiple
// and split out 2026-11-06, once templates placed that rule, so it stays as
// those families ran it. Code otherwise unchanged.
//
// `consecutiveBars` is the CONSOLIDATION LENGTH -- Grimes wants a consolidation
// three or four times the trend's usual five-to-eight-bar pause, and since
// tracking prior consolidation lengths needs machinery no source describes, the
// ratio is baked into a fixed minimum of about 18 bars, the default. AT
// consecutiveBars = 1 THE OUTER LOOP RUNS ONCE ON THE CURRENT BAR AND THIS IS
// EXACTLY RangeWidthBelowAtrMultiple AT lag 0: the window is bars
// 0..rangeLookback-1, and !el_gt(width, K * atr) is el_le(width, K * atr) under
// the same tolerance. The MomentumConsecutiveBars / StrongTrendBarRun precedent
// for a run count.
//
// The window extremes mirror EasyLanguage's Extremes(), which Highest()/
// Lowest() call: seeded at the first bar of the window, scanning the rest,
// strict comparison. Extremes is EL SOURCE, so its comparison carries the
// relational tolerance -- el_gt/el_lt, as in Breakout (the reference). The EL
// twin spells the same nested loop rather than Highest()/Lowest(), because
// the run's shifted window has no registered function spelling.
//
// ONE ATR VALUE FOR THE WHOLE RUN, read at the current bar, never a lagged read
// of WFSafe_AvgTrueRange (QuietBarCountInWindow's arrangement).
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded once with a full sum on the study's first calculated bar and
// thereafter carrying S += TrueRange - TrueRange[Length], re-seeding when the
// length changes. AtrProfitTarget is the reference and carries the measurement
// notes; the two details that are load-bearing are reproduced here -- the
// re-seed on a length change (what makes it walkforward safe) and the update
// as TWO statements, because EasyLanguage evaluates S[1] + in - out left to
// right and folding it to S += in - out rounds differently.
//
// The flag and the accumulators are class members and persist across bars, so
// they are reset before use.
//
// Deepest bar touched: max(rangeLookback + consecutiveBars - 2, atrLookback + 1).
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
tightRun = true;
for (int k = 0; k < (int)consecutiveBars; ++k) {
    rangeHigh = high[k];
    rangeLow = low[k];
    for (int j = 1; j < (int)rangeLookback; ++j) {
        if (el_gt(high[k + j], rangeHigh)) rangeHigh = high[k + j];
        if (el_lt(low[k + j], rangeLow)) rangeLow = low[k + j];
    }
    if (el_gt(rangeHigh - rangeLow, rangeAtrMultiple * atr)) tightRun = false;
}
